questions.solution:
function loadConfig(env) {
  const errors = [];
  const port = Number(env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65535) errors.push(`bad PORT "${env.PORT}"`);
  if (!env.DATABASE_URL) errors.push("DATABASE_URL is required");
  const level = env.LOG_LEVEL ?? "info";
  if (!["debug", "info", "warn", "error"].includes(level)) errors.push(`bad LOG_LEVEL "${level}"`);
  return errors;
}

console.log(loadConfig({ PORT: "30O0", LOG_LEVEL: "verbose" }));
console.log(loadConfig({ DATABASE_URL: "postgres://db/shop" }));

