questions.solution:
function summarize(results) {
  const messages = results.flatMap((r) => r.messages);
  if (messages.length === 0) return "no problems";
  const errors = messages.filter((m) => m.severity === 2).length;
  const warnings = messages.length - errors;
  const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
  return `✖ ${plural(messages.length, "problem")} (${plural(errors, "error")}, ${plural(warnings, "warning")})`;
}

const results = [
  { filePath: "src/cart.js", messages: [{ ruleId: "eqeqeq", severity: 2 }, { ruleId: "prefer-const", severity: 1 }, { ruleId: "no-undef", severity: 2 }] },
  { filePath: "src/format.js", messages: [] },
  { filePath: "src/api.js", messages: [{ ruleId: "no-unused-vars", severity: 2 }, { ruleId: "use-isnan", severity: 2 }] },
];
console.log(summarize(results));
console.log(summarize([{ filePath: "src/ok.js", messages: [] }]));

