questions.solution:
function runChain(steps) {
  const ran = [];
  for (const { name, run } of steps) {
    ran.push(name);
    const exitCode = run();
    if (exitCode !== 0) return { ran, exitCode };
  }
  return { ran, exitCode: 0 };
}

const step = (name, code) => ({ name, run: () => code });
console.log(runChain([step("lint", 0), step("format:check", 1), step("test", 0)]));
console.log(runChain([step("lint", 0), step("format:check", 0), step("test", 0)]));
